BEGIN;
INSERT INTO mission_bridge_permissions(key,description) VALUES('mental_health.medical.read','Read restricted family medical support records') ON CONFLICT DO NOTHING;
INSERT INTO mission_bridge_role_permissions(role_key,permission_key) VALUES('safeguarding_officer','mental_health.medical.read'),('professional_referral_partner','mental_health.medical.read'),('platform_admin','mental_health.medical.read') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS mission_bridge_family_mental_health_profiles(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,owner_user_id TEXT NOT NULL,care_recipient_alias TEXT NOT NULL,medical_detail_encrypted TEXT NOT NULL DEFAULT '',access_class TEXT NOT NULL DEFAULT 'medical_restricted',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(access_class='medical_restricted'));
CREATE TABLE IF NOT EXISTS mission_bridge_relapse_warning_logs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,profile_id UUID NOT NULL REFERENCES mission_bridge_family_mental_health_profiles(id),warning_category TEXT NOT NULL,observation TEXT NOT NULL,risk_level TEXT NOT NULL CHECK(risk_level IN('L0','L1','L2','L3')),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mission_bridge_care_reminders(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,owner_user_id TEXT NOT NULL,reminder_type TEXT NOT NULL CHECK(reminder_type IN('appointment','medication')),label TEXT NOT NULL,schedule JSONB NOT NULL,explicitly_enabled BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mission_bridge_family_crisis_plans(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,owner_user_id TEXT NOT NULL,early_signs JSONB NOT NULL,professional_contacts JSONB NOT NULL,emergency_steps JSONB NOT NULL,family_boundaries JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mission_bridge_family_communication_logs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,owner_user_id TEXT NOT NULL,communication_goal TEXT NOT NULL,what_helped TEXT NOT NULL,private BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(private=TRUE));
CREATE TABLE IF NOT EXISTS mission_bridge_mental_health_education(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,title TEXT NOT NULL,content_id UUID REFERENCES mission_bridge_content_catalog(id),topic TEXT NOT NULL CHECK(topic IN('family_education','stigma','guilt','relapse','crisis')),published BOOLEAN NOT NULL DEFAULT FALSE);
DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['mission_bridge_family_mental_health_profiles','mission_bridge_relapse_warning_logs','mission_bridge_care_reminders','mission_bridge_family_crisis_plans','mission_bridge_family_communication_logs','mission_bridge_mental_health_education'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (tenant_id=current_setting(''app.tenant_id'',true)) WITH CHECK (tenant_id=current_setting(''app.tenant_id'',true))',t);END LOOP;END $$;
COMMIT;
